20	import ComponentView from '../../view/Component';
21	import { HashMap, createHashMap, each } from 'zrender/src/core/util';
22	import MarkerModel from './MarkerModel';
23	import GlobalModel from '../../model/Global';
24	import ExtensionAPI from '../../core/ExtensionAPI';
25	import { makeInner } from '../../util/model';
26	import SeriesModel from '../../model/Series';
27	import Group from 'zrender/src/graphic/Group';
28	import { enterBlur, leaveBlur } from '../../util/states';
29	
30	const inner = makeInner<{
31	    keep: boolean
32	}, MarkerDraw>();
33	
34	interface MarkerDraw {
35	    group: Group
36	}
37	abstract class MarkerView extends ComponentView {
38	
39	    static type = 'marker';
40	    type = MarkerView.type;
41	
42	    /**
43	     * Markline grouped by series
44	     */
45	    markerGroupMap: HashMap<MarkerDraw>;
46	
47	    init() {
48	        this.markerGroupMap = createHashMap();
49	    }
50	
51	    render(markerModel: MarkerModel, ecModel: GlobalModel, api: ExtensionAPI) {
52	        const markerGroupMap = this.markerGroupMap;
53	        markerGroupMap.each(function (item) {
54	            inner(item).keep = false;
55	        });
56	
57	        ecModel.eachSeries(seriesModel => {
58	            const markerModel = MarkerModel.getMarkerModelFromSeries(
59	                seriesModel,
60	                this.type as 'markPoint' | 'markLine' | 'markArea'
61	            );
62	            markerModel && this.renderSeries(seriesModel, markerModel, ecModel, api);
63	        });
64	
65	        markerGroupMap.each(item => {
66	            !inner(item).keep && this.group.remove(item.group);
67	        });
68	    }
69	
70	    markKeep(drawGroup: MarkerDraw) {
71	        inner(drawGroup).keep = true;
72	    }
73	
74	    toggleBlurSeries(seriesModelList: SeriesModel[], isBlur: boolean) {
75	        each(seriesModelList, seriesModel => {
76	            const markerModel = MarkerModel.getMarkerModelFromSeries(
77	                seriesModel,
78	                this.type as 'markPoint' | 'markLine' | 'markArea'
79	            );
80	            if (markerModel) {
81	                const data = markerModel.getData();
82	                data.eachItemGraphicEl(function (el) {
83	                    if (el) {
84	                        isBlur ? enterBlur(el) : leaveBlur(el);
85	                    }
86	                });
87	            }
88	        });
89	    }
90	
91	    abstract renderSeries(
92	        seriesModel: SeriesModel,
93	        markerModel: MarkerModel,
94	        ecModel: GlobalModel,
95	        api: ExtensionAPI
96	    ): void;
97	}
98	
99	export default MarkerView;

