39	function fillLabel(opt: DisplayStateHostOption) {
40	    defaultEmphasis(opt, 'label', ['show']);
41	}
42	
43	export type MarkerStatisticType = 'average' | 'min' | 'max' | 'median';
44	
45	/**
46	 * Option to specify where to put the marker.
47	 */
48	export interface MarkerPositionOption {
49	    // Priority: x/y > coord(xAxis, yAxis) > type
50	
51	    // Absolute position, px or percent string
52	    x?: number | string
53	    y?: number | string
54	
55	    /**
56	     * Coord on any coordinate system
57	     */
58	    coord?: (ScaleDataValue | MarkerStatisticType)[]
59	
60	    // On cartesian coordinate system
61	    xAxis?: ScaleDataValue
62	    yAxis?: ScaleDataValue
63	
64	    // On polar coordinate system
65	    radiusAxis?: ScaleDataValue
66	    angleAxis?: ScaleDataValue
67	
