// Safeguarding test for requirement: marker-formatter-series-context
// Marker label formatter callbacks should receive seriesName / seriesId /
// seriesType of the host series consistently for markPoint, markLine, markArea.
// Run: npx jest --config agent_tests/jest.config.cjs marker-formatter-series-context
import { createChart } from '../test/ut/core/utHelper';
import { CallbackDataParams } from '../src/util/types';

describe('marker-formatter-series-context', function () {

    function makeOption(markerKey: 'markPoint' | 'markLine' | 'markArea', received: { p?: CallbackDataParams }) {
        const marker: any = {
            label: {
                show: true,
                formatter: function (p: CallbackDataParams) {
                    received.p = p;
                    return 'formatted';
                }
            }
        };
        if (markerKey === 'markPoint') {
            marker.data = [{ type: 'max' }];
        }
        else if (markerKey === 'markLine') {
            marker.data = [{ yAxis: 100 }];
        }
        else {
            marker.data = [[{ yAxis: 100 }, { yAxis: 160 }]];
        }
        return {
            xAxis: { type: 'category', data: ['a', 'b', 'c'] },
            yAxis: {},
            series: [{
                id: 'series-id-0',
                name: 'City Alpha',
                type: 'bar',
                data: [165, 170, 30],
                [markerKey]: marker
            }]
        } as any;
    }

    (['markPoint', 'markLine', 'markArea'] as const).forEach(function (markerKey) {
        it(markerKey + ' label formatter callback receives host series info', function () {
            const received: { p?: CallbackDataParams } = {};
            const chart = createChart();
            chart.setOption(makeOption(markerKey, received));

            expect(received.p).toBeTruthy();
            expect(received.p.seriesName).toEqual('City Alpha');
            expect(received.p.seriesId).toEqual('series-id-0');
            expect(received.p.seriesType).toEqual('bar');

            chart.dispose();
        });
    });

});
